/** A config row target, as the API expects it. */

/** `global`, `welcome`, `tag:12`… to `{ scope, scopeId }`. */
export function targetOf(key) {
  const [scope, scopeId = ''] = key.split(':');
  return {
    scope: scope,
    scopeId
  };
}

/**
 * The keys of the configs a target inherits from, from the most general to
 * the closest. For example `['global', 'tag']` for `tag:12`.
 */
export function parentChain(key) {
  const {
    scope,
    scopeId
  } = targetOf(key);
  if (scope === 'global') return [];
  return scopeId ? ['global', scope] : ['global'];
}
flarum.reg.add('walsgit-custom-heroes', 'admin/utils/scopes', { targetOf: targetOf,parentChain: parentChain, });